"""Compare requirements.txt with an offline export of the frozen lockfile."""

import argparse
import subprocess
import sys
from difflib import unified_diff
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
HEADER_PREFIXES = (
    "# Generated from uv.lock",
    "# Regenerate with:",
    "# This file was autogenerated by uv",
    "#    uv export ",
)


def requirements_lines(contents: str) -> list[str]:
    lines = contents.splitlines()
    first = 0
    while first < len(lines) and lines[first].startswith(HEADER_PREFIXES):
        first += 1
    return lines[first:]


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check-lock", action="store_true")
    args = parser.parse_args()
    if args.check_lock:
        locked = subprocess.run(["uv", "lock", "--check", "--offline"], cwd=ROOT, check=False)
        if locked.returncode:
            return locked.returncode

    exported = subprocess.run(
        ["uv", "export", "--frozen", "--offline", "--no-header", "--no-hashes", "--no-dev",
         "--format", "requirements-txt"],
        cwd=ROOT, stdout=subprocess.PIPE, encoding="utf-8", check=False,
    )
    if exported.returncode:
        return exported.returncode
    actual = requirements_lines((ROOT / "requirements.txt").read_text(encoding="utf-8"))
    expected = requirements_lines(exported.stdout)
    if actual != expected:
        for line in unified_diff(actual, expected, "requirements.txt", "uv export", lineterm=""):
            print(line, file=sys.stderr)
        return 1
    print("requirements.txt matches uv export --frozen.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
